defined('ABSPATH') || exit;
add_action('admin_menu',function(){add_submenu_page('edit.php?post_type=tkc_online','Photo submissions','Submissions / 投稿审核','edit_pages','tkcsky-submissions','tkcsky_submissions_admin');add_submenu_page('edit.php?post_type=tkc_online','Sky project setup','Setup / 使用说明','manage_options','tkcsky-setup','tkcsky_setup_admin');});
add_action('add_meta_boxes_tkc_online',function(){add_meta_box('tkcsky-project','Online photo project / 线上照片项目',function($p){wp_nonce_field('tkcsky_project','tkcsky_nonce');$state=get_post_meta($p->ID,'_tkcsky_state',true)?:'paused';echo '<p><label>Submission status / 投稿状态 <select name="tkcsky_state">';foreach(['open'=>'Open / 开放','paused'=>'Paused / 暂停','ended'=>'Ended / 结束']as$key=>$label)echo '<option value="'.esc_attr($key).'" '.selected($state,$key,false).'>'.esc_html($label).'</option>';echo '</select></label></p><p>Open and paused projects appear in Ongoing activities. Ended projects move to Past activities; approved photos remain visible. No deadline is required.</p>';
 foreach(['summary'=>'English card summary / 英文卡片简介','title_et'=>'Estonian title / 爱沙尼亚语标题','summary_et'=>'Estonian card summary / 爱沙尼亚语卡片简介']as$key=>$label)echo '<p><label>'.esc_html($label).'<br><input style="width:100%" name="tkcsky_'.$key.'" value="'.esc_attr(get_post_meta($p->ID,'_tkcsky_'.$key,true)).'"></label></p>';
 echo '<h3>Estonian introduction / 爱沙尼亚语介绍</h3>';wp_editor(get_post_meta($p->ID,'_tkcsky_body_et',true),'tkcsky_body_et',['textarea_name'=>'tkcsky_body_et','textarea_rows'=>8,'media_buttons'=>true]);echo '<p>The main editor is the English introduction. Both languages share the same gallery and submission records. Set a Featured image for the card; otherwise the sky illustration is used.</p>';foreach(get_post_meta($p->ID,'_tkcsky_pages',true)?:[]as$lang=>$page)echo '<p><a href="'.esc_url(get_permalink($page)).'">'.esc_html(strtoupper($lang)).' page</a></p>';
 },'tkc_online','normal','high');});
function tkcsky_sync_pages($id){
 $p=get_post($id);if(!$p||$p->post_type!=='tkc_online'||!in_array($p->post_status,['publish','private','draft'],true))return;$pages=get_post_meta($id,'_tkcsky_pages',true)?:[];if($p->post_status==='draft'&&!$pages)return;$map=get_option('tkc_page_map',[]);$status=$p->post_status;
 foreach(['en','et']as$lang){$data=['post_type'=>'page','post_title'=>tkcsky_field($id,'title',$lang),'post_status'=>$status,'post_content'=>'<!-- wp:shortcode -->[tkc_sky_city id="'.$id.'"]<!-- /wp:shortcode -->','post_parent'=>(int)($map['activities'][$lang]??0),'comment_status'=>'closed'];if(!empty($pages[$lang])&&get_post($pages[$lang])&&(int)get_post_meta($pages[$lang],'_tkcsky_source',true)===$id){$page=(int)$pages[$lang];$data['ID']=$page;}else{$data['post_name']=$id===(int)get_option('tkcsky_primary')?($lang==='en'?'the-sky-the-city':'the-sky-the-city-et'):'online-project-'.$id.($lang==='et'?'-et':'');}$page=isset($data['ID'])?wp_update_post(wp_slash($data),true):wp_insert_post(wp_slash($data),true);if(is_wp_error($page))throw new RuntimeException($page->get_error_message());$pages[$lang]=(int)$page;update_post_meta($page,'_tkcsky_source',$id);if(function_exists('pll_set_post_language'))pll_set_post_language($page,$lang);}
 update_post_meta($id,'_tkcsky_pages',$pages);if(function_exists('pll_save_post_translations'))pll_save_post_translations($pages);
}
add_action('save_post_tkc_online',function($id,$p){if(wp_is_post_revision($id)||wp_is_post_autosave($id)||!current_user_can('edit_post',$id))return;if(isset($_POST['tkcsky_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tkcsky_nonce'])),'tkcsky_project')){$old=get_post_meta($id,'_tkcsky_state',true);$state=sanitize_key($_POST['tkcsky_state']??'paused');if(!in_array($state,['open','paused','ended'],true))$state='paused';update_post_meta($id,'_tkcsky_state',$state);if($state==='ended'&&$old!=='ended')update_post_meta($id,'_tkcsky_ended_at',time());foreach(['summary','summary_et','title_et']as$key)update_post_meta($id,'_tkcsky_'.$key,sanitize_text_field(wp_unslash($_POST['tkcsky_'.$key]??'')));update_post_meta($id,'_tkcsky_body_et',wp_kses_post(wp_unslash($_POST['tkcsky_body_et']??'')));}tkcsky_sync_pages($id);},20,2);
add_action('trashed_post',function($id){if(get_post_type($id)==='tkc_online')foreach(get_post_meta($id,'_tkcsky_pages',true)?:[]as$page)if(get_post_type($page)==='page'&&get_post_status($page)!=='trash')wp_trash_post($page);});
add_action('untrashed_post',function($id){if(get_post_type($id)==='tkc_online')tkcsky_sync_pages($id);});
function tkcsky_submissions_admin(){
 if(!current_user_can('edit_pages'))return;$project=absint($_GET['project']??0);$review=sanitize_key($_GET['review']??'pending');if(!in_array($review,['all','pending','approved','rejected','trash'],true))$review='pending';$entry=absint($_GET['entry']??0);echo '<div class="wrap"><h1>The Sky, The City — Submissions / 投稿审核</h1><p>Photos remain private until approved. Email is only visible here. Reject or move an approved entry to Trash to remove it from the public gallery.</p>';
 if($entry){if(get_post_type($entry)!=='flamingo_inbound'||!get_post_meta($entry,'_tkcsky_project',true)){echo '<p>Submission unavailable.</p></div>';return;}$status=get_post_meta($entry,'_tkcsky_review',true);echo '<h2>'.esc_html(get_post_meta($entry,'_tkcsky_nickname',true)).'</h2><p>Review status: <strong>'.esc_html($status).'</strong> · WordPress status: '.esc_html(get_post_status($entry)).'</p><dl>';foreach(['email'=>'Private email / 私有邮箱','city'=>'City / 城市','message'=>'Message / 留言','consent_at'=>'Public display consent / 公开展示确认时间']as$key=>$label)echo '<dt><strong>'.esc_html($label).'</strong></dt><dd>'.esc_html(get_post_meta($entry,'_tkcsky_'.$key,true)).'</dd>';echo '</dl><p><img style="display:block;max-width:100%;max-height:650px" src="'.esc_url(tkcsky_photo_url($entry,true)).'" alt="Submitted photo"></p>';
 echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcsky_review_'.$entry);echo '<input type="hidden" name="action" value="tkcsky_review"><input type="hidden" name="entry" value="'.$entry.'">';foreach(['approved'=>'Approve / 批准公开','rejected'=>'Reject / 拒绝或撤下','pending'=>'Return to pending / 待审核','trash'=>'Move to Trash / 回收站','restore'=>'Restore to pending / 恢复为待审核']as$key=>$label)echo '<button class="button '.($key==='approved'?'button-primary':'').'" name="review" value="'.$key.'">'.esc_html($label).'</button> ';echo '</form><p><a href="'.esc_url(admin_url('edit.php?post_type=tkc_online&page=tkcsky-submissions')).'">Back to submissions / 返回投稿列表</a></p></div>';return;}
 echo '<form method="get"><input type="hidden" name="post_type" value="tkc_online"><input type="hidden" name="page" value="tkcsky-submissions"><label>Project <select name="project"><option value="0">All projects</option>';foreach(get_posts(['post_type'=>'tkc_online','post_status'=>['publish','private','draft'],'numberposts'=>-1,'suppress_filters'=>true,'lang'=>''])as$p)echo '<option value="'.$p->ID.'" '.selected($project,$p->ID,false).'>'.esc_html($p->post_title).'</option>';echo '</select></label> <label>Review <select name="review">';foreach(['pending'=>'Pending','approved'=>'Approved','rejected'=>'Rejected','all'=>'All active','trash'=>'Trash']as$key=>$label)echo '<option value="'.$key.'" '.selected($review,$key,false).'>'.$label.'</option>';echo '</select></label> <button class="button">Filter</button></form>';
 $meta=[['key'=>'_tkcsky_project','compare'=>$project?'=':'EXISTS']];if($project)$meta[0]['value']=$project;if(in_array($review,['pending','approved','rejected'],true))$meta[]=['key'=>'_tkcsky_review','value'=>$review];$page=max(1,absint($_GET['paged']??1));$q=new WP_Query(['post_type'=>'flamingo_inbound','post_status'=>$review==='trash'?'trash':'publish','posts_per_page'=>20,'paged'=>$page,'lang'=>'','suppress_filters'=>true,'meta_query'=>$meta,'orderby'=>'date','order'=>'DESC']);
 echo '<p>'.(int)$q->found_posts.' submissions</p><table class="widefat striped"><thead><tr><th>Photo</th><th>Nickname / 昵称</th><th>City / 城市</th><th>Private email / 私有邮箱</th><th>Status</th><th>Submitted</th></tr></thead><tbody>';foreach($q->posts as$p){$url=add_query_arg(['post_type'=>'tkc_online','page'=>'tkcsky-submissions','entry'=>$p->ID],admin_url('edit.php'));echo '<tr><td><a href="'.esc_url($url).'"><img src="'.esc_url(add_query_arg('size','thumb',tkcsky_photo_url($p->ID,true))).'" style="max-width:110px;max-height:80px" alt="Review photo"></a></td><td><a href="'.esc_url($url).'">'.esc_html(get_post_meta($p->ID,'_tkcsky_nickname',true)).'</a></td><td>'.esc_html(get_post_meta($p->ID,'_tkcsky_city',true)).'</td><td>'.esc_html(get_post_meta($p->ID,'_tkcsky_email',true)).'</td><td>'.esc_html(get_post_meta($p->ID,'_tkcsky_review',true)).'</td><td>'.esc_html(get_the_date('Y-m-d H:i',$p)).'</td></tr>';}echo '</tbody></table>';if($q->max_num_pages>1)echo '<p>'.paginate_links(['base'=>str_replace('999999999','%#%',esc_url(add_query_arg('paged',999999999))),'current'=>$page,'total'=>$q->max_num_pages]).'</p>';echo '</div>';
}
add_action('admin_post_tkcsky_review',function(){if(!current_user_can('edit_pages'))wp_die('Not authorised.');$id=absint($_POST['entry']??0);check_admin_referer('tkcsky_review_'.$id);if(get_post_type($id)!=='flamingo_inbound'||!get_post_meta($id,'_tkcsky_project',true))wp_die('Invalid entry.');$review=sanitize_key($_POST['review']??'');if($review==='trash')wp_trash_post($id);elseif($review==='restore'){if(get_post_status($id)==='trash'){wp_untrash_post($id);wp_update_post(['ID'=>$id,'post_status'=>'publish']);update_post_meta($id,'_tkcsky_review','pending');}}elseif(in_array($review,['approved','rejected','pending'],true)&&get_post_status($id)==='publish'){if($review==='approved'&&(!tkcsky_photo_path($id)||get_post_meta($id,'_tkcsky_consent',true)!=='public-v1'))wp_die('Photo or consent is missing.');if($review==='approved'&&!get_post_meta($id,'_tkcsky_published_at',true))update_post_meta($id,'_tkcsky_published_at',time());update_post_meta($id,'_tkcsky_review',$review);}wp_safe_redirect(add_query_arg(['post_type'=>'tkc_online','page'=>'tkcsky-submissions','entry'=>$id],admin_url('edit.php')));exit;});
function tkcsky_create_form($lang){
 $et=$lang==='et';$f=WPCF7_ContactForm::get_template(['title'=>'TKC The Sky, The City ['.strtoupper($lang).']','locale'=>$et?'et':'en_GB']);$map=get_option('tkc_page_map',[]);$privacy=get_permalink($map['privacy-policy'][$lang]??0);
 $markup='<p><label>'.($et?'Hüüdnimi *':'Nickname *').' [text* sky-nickname maxlength:80 autocomplete:off]</label></p><p><label>'.($et?'E-post * (ei avaldata)':'Email * (not public)').' [email* sky-email maxlength:254 autocomplete:email]</label></p><p><label>'.($et?'Foto *':'Photo *').' [file* sky-photo filetypes:jpg|jpeg|png|webp limit:5242880]</label><small>'.($et?'Üks JPG-, PNG- või WebP-foto, kuni 5 MB. Fotol peavad olema nii taevas kui ka linn. HEIC-foto ekspordi esmalt JPG-vormingusse.':'One JPG, PNG or WebP photo, up to 5 MB. Include both the sky and a city. Export HEIC photos as JPG first.').'</small></p><p><label>'.($et?'Linn *':'City *').' [text* sky-city maxlength:120]</label></p><p><label>'.($et?'Lühike sõnum (valikuline, kuni 200 tähemärki)':'Short message (optional, up to 200 characters)').' [textarea sky-message maxlength:200]</label></p><div class="tkc-honey" aria-hidden="true"><label>Leave empty [text tkc-website tabindex:-1 autocomplete:off]</label></div><p>[acceptance sky-public]'.($et?'Kinnitan, et mul on õigus seda fotot jagada ning nõustun foto, hüüdnime, linna ja sõnumi avaliku kuvamisega pärast ülevaatamist. Minu e-posti aadress jääb privaatseks.':'I confirm that I have the right to share this image and agree to the public display of my photo, nickname, city and message after review. My email stays private.').'[/acceptance]</p><p><a href="'.esc_url($privacy).'">'.($et?'Privaatsusteave':'Privacy notice').'</a></p><p>[submit "'.($et?'Saada foto':'Submit photo').'"]</p>';
 $messages=$f->prop('messages');$messages=array_merge($messages,['mail_sent_ok'=>$et?'Aitäh oma taeva jagamise eest! Sinu foto on saadetud ülevaatamiseks.':'Thank you for sharing your sky! Your photo has been submitted for review.','mail_sent_ng'=>$et?'Foto salvestamine ei õnnestunud. Palun proovi uuesti.':'Your photo could not be saved. Please try again.','validation_error'=>$et?'Palun kontrolli märgitud välju.':'Please check the highlighted fields.','invalid_required'=>$et?'Palun täida see väli.':'Please fill out this field.','accept_terms'=>$et?'Palun kinnita foto jagamise õigust ja avaldamise nõusolekut.':'Please confirm your right to share the image and permission for public display.','upload_file_too_large'=>$et?'Foto võib olla kuni 5 MB.':'Please use a photo up to 5 MB.','upload_file_type_invalid'=>$et?'Palun vali JPG-, PNG- või WebP-foto.':'Please choose a JPG, PNG or WebP photo.']);$email=tkcs_public_email();
 $f->set_properties(['form'=>$markup,'messages'=>$messages,'mail'=>['active'=>true,'subject'=>'The Sky, The City submission','sender'=>'The Kind Circle <'.$email.'>','recipient'=>$email,'body'=>'Submissions are stored for moderation. Email sending is disabled.','additional_headers'=>'','attachments'=>'','use_html'=>false,'exclude_blank'=>true],'mail_2'=>['active'=>false],'additional_settings'=>"skip_mail: on\nacceptance_as_validation: on\nflamingo_name: \"[sky-nickname]\"\nflamingo_subject: \"The Sky, The City\""]);$f->save();return (int)$f->id();
}
function tkcsky_setup_admin(){
 if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>The Sky, The City — setup / 使用说明</h1><p>Online projects maintains title, introduction, cover and Open / Paused / Ended status. English and Estonian pages share one moderated gallery. Manage submissions in Submissions; approved entries appear publicly without email. No submission emails or newsletter subscriptions are sent.</p>';
 if(!get_option('tkcsky_setup_v1')){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcsky_install');echo '<input type="hidden" name="action" value="tkcsky_install"><p>Create the real The Sky, The City project, bilingual pages and forms; update Home/Activities online listings and append the privacy explanation. Existing page content is backed up before replacement.</p>';submit_button('Set up The Sky, The City');echo '</form>';}
 else{echo '<p>Setup complete.</p>';foreach(get_post_meta((int)get_option('tkcsky_primary'),'_tkcsky_pages',true)?:[]as$lang=>$page)echo '<p><a href="'.esc_url(get_permalink($page)).'">'.strtoupper($lang).' project page</a></p>';echo '<p><a href="'.esc_url(get_edit_post_link((int)get_option('tkcsky_primary'))).'">Edit project / 编辑项目</a></p>';}
 echo '<h2>Maintenance / 维护</h2><ol><li>Online projects → edit The Sky, The City: edit English and Estonian introductions and card summaries; optionally set a Featured image.</li><li>Open allows submissions; Paused closes the form and remains Ongoing; Ended moves the project to Past. Approved photos remain viewable.</li><li>Submissions → Pending: open a photo, review city/message/private email, then Approve or Reject. Rejected and pending photos are not publicly accessible. Trash hides photos immediately; Restore returns them to Pending.</li><li>Contact → TKC The Sky, The City [EN]/[ET] maintains form labels. Preserve required field names, limits and consent. This project has no likes, comments, voting or maps.</li></ol><p>Photos (full and thumbnails) are stored with the existing protected images outside the public web directory. Include that directory in hosting backups; the authenticated export below includes both photos and private contact data. Content XML alone does not include the files. Remove records according to the website retention policy; permanent deletion also deletes photo files.</p>';
 if(class_exists('ZipArchive')){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcsky_export');echo '<input type="hidden" name="action" value="tkcsky_export">';submit_button('Download private sky submission backup','secondary');echo '</form>';}
 echo '<h2>Private verification / 私有验收</h2><p>A separate private project and pages are visible only to managers and excluded from public activity lists.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcsky_test');echo '<input type="hidden" name="action" value="tkcsky_test">';$test=(int)get_option('tkcsky_test');if($test&&get_post_status($test)==='private'){foreach(get_post_meta($test,'_tkcsky_pages',true)?:[]as$lang=>$page)echo '<p><a href="'.esc_url(get_permalink($page)).'">'.strtoupper($lang).' private verification</a></p>';echo '<button class="button" name="cleanup" value="1">Move verification project and submissions to Trash</button>';}else echo '<button class="button">Create private verification project</button>';echo '</form></div>';
}
function tkcsky_project_defaults($private=false){
 $p=wp_insert_post(['post_type'=>'tkc_online','post_status'=>'draft','post_title'=>$private?'Private Sky Verification':'The Sky, The City','post_content'=>'<p>Life gets busy. Sometimes, all we need is a moment to pause and look up.</p><p>From quiet mornings to colourful sunsets, every city has its own sky. Share a little beauty from where you are, and discover the skies above cities around the world.</p><h2>How to take part</h2><p>Share one photo featuring both the sky and a city. Enter your city, choose a nickname and optionally add a short message. Your photo will appear after review.</p>']);if(!$p||is_wp_error($p))throw new RuntimeException('Project could not be created.');if(!$private)update_option('tkcsky_primary',$p,false);
 foreach(['state'=>'open','summary'=>'Pause, look up, and share the sky above your city.','summary_et'=>'Peatu hetkeks, vaata üles ja jaga oma linna taevast.','title_et'=>$private?'Privaatne taeva testi projekt':'The Sky, The City','body_et'=>'<p>Elu on kiire. Mõnikord piisab hetkest, et peatuda ja vaadata üles.</p><p>Vaiksetest hommikutest värviliste loojanguteni — igal linnal on oma taevas. Jaga killukest ilu oma asukohast ning avasta linnade taevast üle maailma.</p><h2>Kuidas osaleda</h2><p>Jaga üht fotot, millel on nii taevas kui ka linn. Sisesta linn, vali hüüdnimi ja lisa soovi korral lühike sõnum. Foto avaldatakse pärast ülevaatamist.</p>']as$key=>$value)update_post_meta($p,'_tkcsky_'.$key,$value);wp_update_post(['ID'=>$p,'post_status'=>$private?'private':'publish']);return $p;
}
add_action('admin_post_tkcsky_install',function(){
 if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcsky_install');if(get_option('tkcsky_setup_v1')){wp_safe_redirect(admin_url('edit.php?post_type=tkc_online&page=tkcsky-setup'));exit;}if(!class_exists('WPCF7_ContactForm')||!class_exists('Flamingo_Inbound_Message')||is_wp_error(tkcq_private_dir(true)))wp_die('Forms or protected photo storage unavailable.');
 $map=get_option('tkc_page_map',[]);$prepared=[];$backup=['at'=>gmdate('c'),'pages'=>[]];foreach(['home','activities','privacy-policy']as$key)foreach(['en','et']as$lang){$id=(int)($map[$key][$lang]??0);$p=get_post($id);if(!$p)wp_die('Required page missing. No listing changes applied.');$backup['pages'][$id]=$p->post_content;$content=$p->post_content;if($key!=='privacy-policy'){$content=str_replace('[tkc_city_surprise','[tkc_online_activities',$content,$count);if(!$count)wp_die('Online listing source changed. No listing changes applied.');if($key==='activities'){$blocks=parse_blocks($content);$strip=function($nodes)use(&$strip){foreach($nodes as&$node){if($node['blockName']==='core/column'&&strpos($node['attrs']['className']??'','tkcq-online')!==false){foreach($node['innerBlocks']as$i=>$child){$text=trim(wp_strip_all_tags(serialize_block($child)));if($child['blockName']==='core/paragraph'&&($text==='City Surprise'||strpos($text,'Explore Tallinn, one clue at a time.')===0||strpos($text,'Avasta Tallinnat ühe vihje kaupa.')===0)){unset($node['innerBlocks'][$i]);}}$node['innerBlocks']=array_values($node['innerBlocks']);$node['innerContent']=array_merge([reset($node['innerContent'])],array_fill(0,count($node['innerBlocks']),null),[end($node['innerContent'])]);}elseif(!empty($node['innerBlocks']))$node['innerBlocks']=$strip($node['innerBlocks']);}unset($node);return $nodes;};$content=serialize_blocks($strip($blocks));}}else{$text=$lang==='et'?'Projektis The Sky, The City kogume hüüdnime, e-posti aadressi, foto, linna ja vabatahtliku lühisõnumi. Pärast nõusolekut ja korraldajate ülevaatamist avaldatakse foto, hüüdnimi, linn, sõnum ja avaldamise kuupäev. E-posti aadress on nähtav ainult korraldajatele osalemisega seotud ühenduse võtmiseks; seda ei avaldata. GPS-asukohta ei küsita ning fotost eemaldatakse manustatud metaandmed enne kuvamist. Üleslaadimine ei lisa sind uudiskirja saajate hulka. Kohaldame eespool kirjeldatud tegevusandmete säilitamise korda. Foto eemaldamiseks võta meiega ühendust.':'For The Sky, The City we collect your nickname, email, photo, city and optional short message. With your consent and after organiser review, your photo, nickname, city, message and publication date are displayed publicly. Your email is visible only to organisers for participation-related contact and is never displayed publicly. We do not request GPS location and remove embedded image metadata before display. Taking part does not subscribe you to newsletters. The activity-record retention policy above applies. Contact us to request removal of a photo.';$content.="\n".'<!-- wp:heading --><h2 class="wp-block-heading" id="tkcsky-privacy">The Sky, The City</h2><!-- /wp:heading --><!-- wp:paragraph --><p>'.esc_html($text).'</p><!-- /wp:paragraph -->';}$prepared[$id]=$content;}
 update_option('tkcsky_setup_backup',$backup,false);$forms=get_option('tkcsky_forms',[]);foreach(['en','et']as$lang)if(empty($forms[$lang])){$forms[$lang]=tkcsky_create_form($lang);update_option('tkcsky_forms',$forms,false);}if(!get_post((int)get_option('tkcsky_primary')))tkcsky_project_defaults();
 foreach($prepared as$id=>$content){$r=wp_update_post(wp_slash(['ID'=>$id,'post_content'=>$content]),true);if(is_wp_error($r))wp_die(esc_html($r->get_error_message()));}update_option('tkcsky_setup_v1',gmdate('c'),false);wp_safe_redirect(admin_url('edit.php?post_type=tkc_online&page=tkcsky-setup'));exit;
});
add_action('admin_post_tkcsky_test',function(){if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcsky_test');$test=(int)get_option('tkcsky_test');if(!empty($_POST['cleanup'])){if($test&&get_post_status($test)==='private'){foreach(get_posts(['post_type'=>'flamingo_inbound','post_status'=>'publish','numberposts'=>-1,'lang'=>'','suppress_filters'=>true,'meta_key'=>'_tkcsky_project','meta_value'=>$test])as$p)wp_trash_post($p->ID);wp_trash_post($test);}update_option('tkcsky_test',0,false);}elseif(!$test||get_post_status($test)!=='private')update_option('tkcsky_test',tkcsky_project_defaults(true),false);wp_safe_redirect(admin_url('edit.php?post_type=tkc_online&page=tkcsky-setup'));exit;});
add_action('admin_post_tkcsky_export',function(){if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcsky_export');if(!class_exists('ZipArchive'))wp_die('ZIP unavailable.');$tmp=wp_tempnam('sky-backup');$zip=new ZipArchive();if($zip->open($tmp,ZipArchive::OVERWRITE)!==true)wp_die('Backup unavailable.');$data=[];foreach(get_posts(['post_type'=>'flamingo_inbound','post_status'=>['publish','trash'],'numberposts'=>-1,'lang'=>'','suppress_filters'=>true,'meta_query'=>[['key'=>'_tkcsky_project','compare'=>'EXISTS']]])as$p){$row=['id'=>$p->ID,'status'=>$p->post_status,'submitted'=>$p->post_date_gmt];foreach(['project','nickname','email','city','message','review','published_at','consent','consent_at','language']as$key)$row[$key]=get_post_meta($p->ID,'_tkcsky_'.$key,true);foreach([false,true]as$thumb){$path=tkcsky_photo_path($p->ID,$thumb);if($path){$name='photos/'.basename($path);$row[$thumb?'thumbnail':'photo']=$name;$zip->addFile($path,$name);}}$data[]=$row;}$zip->addFromString('submissions-private.json',wp_json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$zip->close();nocache_headers();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="sky-city-private-backup.zip"');header('Content-Length: '.filesize($tmp));readfile($tmp);wp_delete_file($tmp);exit;});
